    // NOVA VERIFICAÇÃO ADICIONADA - Tratar mensagens com links formatados
    if (!message.includes('<imagem>') && !message.includes('<video>') && !message.includes('<audio>') && !message.includes('<documento>')) {
        const linkResult = extractLinkFromFormattedMessage(message);

        if (linkResult && linkResult.success) {
            // Mapear tipo para Evolution API
            let evolutionType;
            switch (linkResult.detectedType) {
                case 'imagem':
                    evolutionType = 'image';
