                mediaType: evolutionType,
                url: linkResult.url,
                detectedType: linkResult.detectedType,
                method: linkResult.method,
                originalMessage: message,
                info: "Link extraído de mensagem formatada"
            };
        }
    }

    // Verificar especificamente se tem tag <imagem>
    if (message.includes('<imagem>') && message.includes('</imagem>')) {
        const imageResult = extractImageURL(message);

        if (imageResult) {
            if (imageResult.success) {
                return {
                    hasMedia: true,
                    mediaType: 'image', // Para Evolution API
                    url: imageResult.url,
                    tagType: imageResult.tipo,
                    detectedType: imageResult.detectedType,
                    method: 'image_tag_extraction',
                    originalMessage: message
                };
            } else {
                return {
                    error: imageResult.error,
                    hasMedia: false,
                    debug: { 
                        url: imageResult.url,
                        originalMessage: message 
                    }
                };
            }
        }
    }

    // Verificar outras tags de mídia
    const mediaResults = extractMediaFromTags(message);

    if (mediaResults && mediaResults.length > 0) {
        // Pegar primeira mídia válida
        const validMedia = mediaResults.find(m => m.valid);

        if (validMedia) {
            // Mapear tipo para Evolution API
            let evolutionType;
            switch (validMedia.detectedType) {
                case 'imagem':
                    evolutionType = 'image';
                    break;
                case 'video':
                    evolutionType = 'video';
                    break;
                case 'audio':
                    evolutionType = 'audio';
                    break;
                case 'documento':
                    evolutionType = 'document';
                    break;
                default:
                    evolutionType = 'document';
            }

            return {
                hasMedia: true,
                mediaType: evolutionType,
                url: validMedia.url,
                tagType: validMedia.tagType,
                detectedType: validMedia.detectedType,
                method: 'media_tag_extraction',
                allResults: mediaResults,
                originalMessage: message
            };
        } else {
            return {
                error: "Tags de mídia encontradas mas nenhuma URL válida",
                hasMedia: false,
                debug: { 
                    results: mediaResults,
                    originalMessage: message 
                }
            };
        }
    }

    // Nenhuma tag de mídia encontrada
    return {
        hasMedia: false,
        isTextOnly: true,
        message: message,
        info: "Mensagem não contém tags de mídia"
